from __future__ import annotations

import re

_DIGITS = "0123456789"

_PRE_ID = r"(?:[0-9]*[A-Za-z-][0-9A-Za-z-]*|0|[1-9][0-9]*)"
_VERSION_RE = re.compile(
    rf"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    rf"(?:-({_PRE_ID}(?:\.{_PRE_ID})*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?\Z"
)


def _is_number(s: str) -> bool:
    return bool(s) and all(c in _DIGITS for c in s)


def _pre_component_key(ident: str):
    if all(c in _DIGITS for c in ident):
        return (0, int(ident), "")
    return (1, 0, ident)


def _version_key(major, minor, patch, pre_ids):
    if pre_ids is None:
        return (major, minor, patch, 1, ())
    return (major, minor, patch, 0, tuple(_pre_component_key(i) for i in pre_ids))


def _parse_version(s: str, allow_build: bool = True):
    if not isinstance(s, str):
        return None
    m = _VERSION_RE.fullmatch(s)
    if not m:
        return None
    if not allow_build and m.group(5) is not None:
        return None

    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    pre_ids = None
    if m.group(4) is not None:
        pre_ids = m.group(4).split(".")

    key = _version_key(major, minor, patch, pre_ids)
    return (key, major, minor, patch, pre_ids)


def _partial_base(nums):
    arr = [0, 0, 0]
    for i, n in enumerate(nums):
        arr[i] = n
    return tuple(arr)


def _partial_next(nums):
    arr = list(_partial_base(nums))
    arr[len(nums) - 1] += 1
    for i in range(len(nums), 3):
        arr[i] = 0
    return tuple(arr)


def _partial_caret_upper(nums):
    arr = list(_partial_base(nums))
    idx = None
    for i, n in enumerate(nums):
        if n != 0:
            idx = i
            break
    if idx is None:
        idx = len(nums) - 1
    arr[idx] += 1
    for i in range(idx + 1, 3):
        arr[i] = 0
    return tuple(arr)


def _parse_pattern(s: str):
    if s == "":
        raise ValueError("empty pattern")
    if "+" in s:
        raise ValueError("build metadata is not allowed in range patterns")

    if "-" in s:
        v = _parse_version(s, allow_build=False)
        if v is None:
            raise ValueError("invalid pattern")
        return ("full", v)

    parts = s.split(".")
    if len(parts) > 3:
        raise ValueError("invalid pattern")

    seen_wild = False
    nums = []

    for part in parts:
        if part == "":
            raise ValueError("invalid pattern")
        if part in ("x", "X", "*"):
            seen_wild = True
        else:
            if seen_wild:
                raise ValueError("invalid pattern")
            if not _is_number(part):
                raise ValueError("invalid pattern")
            if len(part) > 1 and part[0] == "0":
                raise ValueError("invalid pattern")
            nums.append(int(part))

    if not nums:
        return ("any", None)

    if len(parts) == 3 and len(nums) == 3:
        v = _parse_version(s, allow_build=False)
        if v is None:
            raise ValueError("invalid pattern")
        return ("full", v)

    return ("partial", tuple(nums))


def _make_predicate(op, kind, data):
    if kind == "any":
        if op is not None:
            raise ValueError("operator is not allowed on a pattern without a number")
        return lambda key: True

    if kind == "partial":
        nums = data
        base = _partial_base(nums)
        lower = _version_key(base[0], base[1], base[2], None)
        lower_pre0 = _version_key(base[0], base[1], base[2], ("0",))

        if op in (None, "="):
            upper_base = _partial_next(nums)
            upper = _version_key(upper_base[0], upper_base[1], upper_base[2], ("0",))
            return lambda key: lower <= key < upper

        if op == ">":
            next_base = _partial_next(nums)
            lower_next = _version_key(next_base[0], next_base[1], next_base[2], None)
            return lambda key: key >= lower_next

        if op == ">=":
            return lambda key: key >= lower

        if op == "<":
            return lambda key: key < lower_pre0

        if op == "<=":
            upper_base = _partial_next(nums)
            upper = _version_key(upper_base[0], upper_base[1], upper_base[2], ("0",))
            return lambda key: key < upper

        if op == "~":
            upper_base = _partial_next(nums)
            upper = _version_key(upper_base[0], upper_base[1], upper_base[2], ("0",))
            return lambda key: lower <= key < upper

        if op == "^":
            upper_base = _partial_caret_upper(nums)
            upper = _version_key(upper_base[0], upper_base[1], upper_base[2], ("0",))
            return lambda key: lower <= key < upper

    # Full version pattern.
    key0, major, minor, patch, pre_ids = data

    if op in (None, "="):
        return lambda key: key == key0

    if op == ">":
        return lambda key: key > key0

    if op == ">=":
        return lambda key: key >= key0

    if op == "<":
        return lambda key: key < key0

    if op == "<=":
        return lambda key: key <= key0

    if op == "~":
        upper = _version_key(major, minor + 1, 0, ("0",))
        return lambda key: key0 <= key < upper

    if op == "^":
        arr = [major, minor, patch]
        idx = None
        for i, value in enumerate(arr):
            if value != 0:
                idx = i
                break
        if idx is None:
            idx = 2
        arr[idx] += 1
        for i in range(idx + 1, 3):
            arr[i] = 0
        upper = _version_key(arr[0], arr[1], arr[2], ("0",))
        return lambda key: key0 <= key < upper

    raise ValueError("unknown operator")


def _parse_alternative(text: str):
    tokens = [t for t in text.split(" ") if t != ""]
    if not tokens:
        raise ValueError("empty alternative")

    predicates = []
    allowed_pre_mmpps = set()

    for token in tokens:
        if token.startswith("<="):
            op, rest = "<=", token[2:]
        elif token.startswith(">="):
            op, rest = ">=", token[2:]
        elif token.startswith("<"):
            op, rest = "<", token[1:]
        elif token.startswith(">"):
            op, rest = ">", token[1:]
        elif token.startswith("="):
            op, rest = "=", token[1:]
        elif token.startswith("^"):
            op, rest = "^", token[1:]
        elif token.startswith("~"):
            op, rest = "~", token[1:]
        else:
            op, rest = None, token

        if rest == "":
            raise ValueError("empty pattern")

        kind, data = _parse_pattern(rest)

        if op is not None and kind == "any":
            raise ValueError("operator is not allowed on a pattern without a number")

        predicates.append(_make_predicate(op, kind, data))

        if kind == "full" and data[4] is not None:
            allowed_pre_mmpps.add((data[1], data[2], data[3]))

    return predicates, allowed_pre_mmpps


def _parse_range(expr: str):
    if not isinstance(expr, str):
        raise ValueError("range must be a string")

    expr = expr.strip(" ")
    if expr == "":
        raise ValueError("empty range")

    alternatives = []
    for part in expr.split("||"):
        if part.strip(" ") == "":
            raise ValueError("empty alternative")
        alternatives.append(_parse_alternative(part))

    return alternatives


def best_match(versions: list[str], range_expr: str) -> str | None:
    if not versions:
        raise ValueError("versions is empty")

    alternatives = _parse_range(range_expr)

    best_key = None
    best_version = None

    for original in versions:
        parsed = _parse_version(original, allow_build=True)
        if parsed is None:
            continue

        key, major, minor, patch, pre_ids = parsed

        for predicates, allowed_pre_mmpps in alternatives:
            satisfies = True
            for predicate in predicates:
                if not predicate(key):
                    satisfies = False
                    break

            if not satisfies:
                continue

            if pre_ids is not None and (major, minor, patch) not in allowed_pre_mmpps:
                continue

            if best_key is None or key > best_key:
                best_key = key
                best_version = original

            break

    return best_version
